import{_ as r,l as p,o as n,b as s,q as d,d as a,f as e,m}from"./chunks/framework.Tf23FRXt.js";const f=JSON.parse('{"title":"终结之战","description":"","frontmatter":{},"headers":[],"relativePath":"duty/796.htm.md","filePath":"duty/796.md","lastUpdated":1791098838000}'),l={name:"duty/796.htm.md"};function _(i,t,O,S,A,u){const o=p("Role");return n(),s("div",null,[t[4]||(t[4]=d('<h1 id="终结之战" tabindex="-1">终结之战</h1><p>场边会跌落，注意不要掉下去了。大原则是出啥躲啥，场边出现的钻缝，场内出现的远离，点名的散开。LB 需要由 T 使用，其他人不要抢。</p><p>开场 AOE 后，场地上会出现两颗星球，当跑的快的星球追上跑的慢的星球时会发生 AOE，躲开跑的慢的星球即可。</p><p>读条<mark>反诘</mark>时观察 BOSS，张嘴发光时中央 AOE，闭嘴流眼泪时两侧 AOE。</p><p>读条<mark>死亡拥抱</mark>后，从场地最北端向玩家发射扇形 AOE，注意散开，AOE 后落下羽毛，羽毛会再次造成圆形 AOE，注意躲开羽毛。</p><p>后半场星球相撞会追加回溯功能，即同一个位置会爆发两次（第二次有很～～长的动画，会有其他机制同时出现）。</p><p>再往后会同时出现 2 组相撞的星球，需要观察 BOSS 连线判断哪组星球先回溯，连线的位置就是将要出现 AOE 范围的位置，注意会有其他机制同时出现。</p>',7)),a("p",null,[t[0]||(t[0]=e("打完小怪后 BOSS 会使用",-1)),t[1]||(t[1]=a("mark",null,"究极命运",-1)),t[2]||(t[2]=e("，当屏幕提示还剩 5~4s 的时候，",-1)),m(o,{name:"tank"}),t[3]||(t[3]=e("T 注意务必使用 3 格 LB 做减伤。之后 BOSS 会再次使用究极命运。",-1))])])}const B=r(l,[["render",_]]);export{f as __pageData,B as default};
